window.__ModuleLoader__.load({
  id: 'dsh-yourdeepfish',
  factory: function (require) {
    var module = { exports: {} };
    var exports = module.exports;
    Object.defineProperty(exports, Symbol.toStringTag, { value: 'Module' });
    var React = require('react');
    var h = React.createElement;

    var NS = 'yourdeepfish';
    // 客户端插件必须声明依赖的服务，否则访问 ctx.slots 会抛
    // "cannot get property \"slots\" without inject"
    var inject = ['slots'];
    var POSES = {
      idle: 'data:image/png;base64,',
      happy: 'data:image/png;base64,',
      sleep: 'data:image/png;base64,',
    };
    var LINES = [
      '主人，您回来啦。茶已经沏好了……才、才不是特意等您呢。',
      '欢迎回来，主人。房间打扫过了，杯子也擦干净了。',
      '哼、主人怎么才回来！我才没有等很久。',
      '主人，已经坐了很久了。起来活动一下比较好。',
    ];

    var W = 96;
    var H = 136;

    function PetOverlay() {
      var canvasRef = React.useRef(null);
      var bubbleRef = React.useRef(null);
      var stateRef = React.useRef({ pose: 'idle', happyUntil: 0, lastClick: 0 });

      React.useEffect(function () {
        var canvas = canvasRef.current;
        if (!canvas) return undefined;
        var ctx = canvas.getContext('2d');
        var dpr = Math.min(2, window.devicePixelRatio || 1);
        canvas.width = W * dpr;
        canvas.height = H * dpr;
        ctx.scale(dpr, dpr);

        var images = {};
        Object.keys(POSES).forEach(function (key) {
          var img = new Image();
          img.src = POSES[key];
          img.onload = function () {
            images[key] = img;
          };
        });

        var raf = 0;
        var start = performance.now();

        function frame(now) {
          var t = (now - start) / 1000;
          var st = stateRef.current;
          if (st.happyUntil && now > st.happyUntil) {
            st.happyUntil = 0;
            st.pose = 'idle';
          }
          var pose = st.pose === 'happy' ? 'happy' : st.pose;
          var img = images[pose] || images.idle;
          ctx.clearRect(0, 0, W, H);
          if (img) {
            var breath = Math.sin((t * Math.PI * 2) / 3.4);
            var sway = Math.sin((t * Math.PI * 2) / 4.8);
            var hh = 126;
            var ww = (hh * img.width) / img.height;
            ctx.save();
            ctx.translate(W / 2, H - 6);
            ctx.rotate(sway * 0.012);
            ctx.scale(1 + 0.012 * breath, 1 - 0.016 * breath);
            ctx.drawImage(img, -ww / 2, -hh, ww, hh);
            ctx.restore();
          }
          raf = requestAnimationFrame(frame);
        }
        raf = requestAnimationFrame(frame);

        // 连接本地内核（和桌面外壳同一份 WS），收到 say 就弹气泡
        var socket = null;
        var retry = 0;
        var retryTimer = 0;
        function connect() {
          try {
            socket = new WebSocket('ws://127.0.0.1:45871');
          } catch (e) {
            return;
          }
          socket.onopen = function () {
            retry = 0;
            try {
              socket.send(JSON.stringify({ type: 'hello', shell: 'dsh-plugin' }));
            } catch (e) {
              /* ignore */
            }
          };
          socket.onmessage = function (ev) {
            try {
              var msg = JSON.parse(ev.data);
              if (msg && msg.type === 'say') {
                showBubble(msg.text);
                stateRef.current.pose = 'happy';
                stateRef.current.happyUntil = performance.now() + 3000;
              }
            } catch (e) {
              /* ignore */
            }
          };
          socket.onclose = function () {
            socket = null;
            retryTimer = window.setTimeout(connect, Math.min(15000, 2000 * (++retry)));
          };
          socket.onerror = function () {
            try {
              socket.close();
            } catch (e) {
              /* ignore */
            }
          };
        }
        connect();

        return function () {
          cancelAnimationFrame(raf);
          window.clearTimeout(retryTimer);
          if (socket) {
            try {
              socket.close();
            } catch (e) {
              /* ignore */
            }
          }
        };
      }, []);

      function showBubble(text) {
        var bubble = bubbleRef.current;
        if (!bubble || !text) return;
        bubble.textContent = text;
        bubble.style.opacity = '1';
        var st = stateRef.current;
        clearTimeout(st.timer);
        st.timer = setTimeout(function () {
          bubble.style.opacity = '0';
        }, 6000);
      }

      function onClick() {
        var st = stateRef.current;
        st.pose = 'happy';
        st.happyUntil = performance.now() + 3000;
        showBubble(LINES[Math.floor(Math.random() * LINES.length)]);
      }

      return h(
        'div',
        {
          style: {
            position: 'fixed',
            right: '28px',
            bottom: '16px',
            width: W + 'px',
            height: H + 'px',
            zIndex: 60,
            pointerEvents: 'none',
          },
        },
        h('div', {
          ref: bubbleRef,
          style: {
            position: 'absolute',
            top: '0px',
            right: '0px',
            width: '196px',
            padding: '8px 12px',
            borderRadius: '14px',
            background: 'rgba(255,255,255,0.96)',
            color: '#2b3a67',
            font: '12.5px/1.5 "Microsoft YaHei", sans-serif',
            boxShadow: '0 6px 18px rgba(38,64,140,0.22)',
            opacity: 0,
            transition: 'opacity .2s ease',
            pointerEvents: 'none',
          },
        }),
        h('canvas', {
          ref: canvasRef,
          onClick: onClick,
          style: {
            width: W + 'px',
            height: H + 'px',
            pointerEvents: 'auto',
            cursor: 'pointer',
          },
        }),
      );
    }

    function apply(ctx) {
      // 注册失败不能让整个 web boot 挂掉：宿主把 apply 抛错当成 entry failed，
      // 会直接阻断启动。这里兜住所有异常，只在控制台留一条记录。
      try {
        if (!ctx || !ctx.slots) {
          console.error('[yourdeepfish] ctx.slots 不可用，跳过悬浮层注册');
          return;
        }
        ctx.slots.inject('shell.overlay', function () {
          return ctx.slots.register(
            { name: 'shell.overlay', id: 'dsh-yourdeepfish', order: 90 },
            PetOverlay,
          );
        });
      } catch (error) {
        console.error('[yourdeepfish] 注册悬浮层失败:', error);
      }
    }

    exports.inject = inject;
    exports.apply = apply;
    exports.NS = NS;
    return module.exports;
  },
});
